        /*
        * Keyboard accessibility — focus rings, card navigation, drawer nav fix.
        *
        * Why inline styles?
        *   MudBlazor's CSS resets `outline: none` on buttons and anchors globally.
        *   Inline styles have higher specificity than any stylesheet rule, so they
        *   always win regardless of load order or MudBlazor version updates.
        *
        * Why capture phase (third arg = true on addEventListener)?
        *   Capture phase fires before bubble phase, so our ring logic runs before
        *   any component-level handlers can cancel propagation and swallow the event.
        */
        (function () {
        // Fallback colour used if the MudBlazor CSS variable isn't available yet
        // (e.g. before the stylesheet loads or in environments without theming).
        var FALLBACK_FOCUS_COLOR = '#594AE2';

        // ── Colour helper ──────────────────────────────────────────────────────────
        // Always reads the live CSS variable so the ring automatically follows
        // theme changes without needing a JS-side theme listener.
        function getFocusRingColor() {
        var cssValue = getComputedStyle(document.documentElement)
        .getPropertyValue('--mud-palette-primary');
        return cssValue && cssValue.trim() ? cssValue.trim() : FALLBACK_FOCUS_COLOR;
        }

        // ── Interactive-element resolver ───────────────────────────────────────────
        // Given any element that received focus, returns the element that should
        // display the ring. Priority order matters:
        //   1. Expansion panel headers — full-width, checked before generic selectors
        //      so a click on child text still highlights the whole header row.
        //   2. Tiled-menu tiles — excluded because selectInterop.js draws their ring
        //      on the inner tile element; drawing it here too would produce a double ring.
        //   3. Native <a> and <button> — the standard interactive elements.
        function findRingTarget(focusedElement) {
        if (!focusedElement) return null;

        // Panel header — match both the header itself and any child element inside it.
        if (focusedElement.matches('.mud-expand-panel-header')) return focusedElement;
        var panelHeader = focusedElement.closest
        ? focusedElement.closest('.mud-expand-panel-header')
        : null;
        if (panelHeader) return panelHeader;

        // Tiled-menu tiles have their own ring; skip them here.
        if (focusedElement.closest && focusedElement.closest('.tedx-tiled-menu-tile-link'))
        return null;

        // Standard interactive elements.
        if (focusedElement.matches('a, button')) return focusedElement;
        return focusedElement.closest ? focusedElement.closest('a, button') : null;
        }

        // ── Focus ring: apply on focus, remove on blur ─────────────────────────────
        document.addEventListener('focusin', function (e) {
        var ringTarget = findRingTarget(e.target);
        if (!ringTarget) return;

        // Expansion panels get an inset ring (negative offset) with a larger radius
        // so it follows the panel's rounded corners; links/buttons get a tighter ring.
        var isExpansionPanel = ringTarget.classList.contains('mud-expand-panel-header');

        ringTarget.style.outline       = '2px solid ' + getFocusRingColor();
        ringTarget.style.outlineOffset = isExpansionPanel ? '-2px' : '-1px';
        ringTarget.style.borderRadius  = isExpansionPanel ? '8px'  : '3px';
        }, true);

        document.addEventListener('focusout', function (e) {
        var ringTarget = findRingTarget(e.target);
        if (!ringTarget) return;
        ringTarget.style.outline       = '';
        ringTarget.style.outlineOffset = '';
        ringTarget.style.borderRadius  = '';
        }, true);

        // ── Expansion panel tab-stop + ARIA enforcement ────────────────────────────
        // MudBlazor 8.x renders panel headers as <div tabIndex="-1"> with no role or
        // aria-expanded. Force tabIndex=0, stamp role="button", and reflect the
        // expanded state via aria-expanded so screen readers can announce correctly.
        // The MutationObserver below re-runs this after every DOM update, keeping
        // aria-expanded in sync whenever a panel is toggled.
        function ensureExpansionPanelsAreReachable() {
        document.querySelectorAll('.mud-expand-panel-header').forEach(function (header) {
        if (header.tabIndex < 0) header.tabIndex = 0;

        if (header.tagName.toLowerCase() !== 'button' && !header.getAttribute('role')) {
        header.setAttribute('role', 'button');
        }

        var panel = header.closest('.mud-expand-panel');
        if (panel) {
        var content = panel.querySelector('.mud-expand-panel-content');
        var isExpanded = content ? content.offsetHeight > 0 : false;
        header.setAttribute('aria-expanded', isExpanded ? 'true' : 'false');
        }
        });
        }

        // ── Card roving-tabindex navigation ────────────────────────────────────────
        // Pattern: Tab cycles between card containers (tabIndex=0 on the card itself).
        //   Enter  → "enter" the card: remove the card from the tab order, promote
        //            its inner actions to tabIndex=0, focus the first one.
        //   Escape → "exit" the card: restore the card's tabIndex=0, hide inner
        //            actions from tab order, return focus to the card container.
        //   Blur   → auto-exit if focus leaves the card entirely (e.g. user clicks
        //            outside or Tabs past the last inner action).
        var CARD_SELECTOR       = '.upcoming-election-card-focusable, .wdiv-location-card';
        var INNER_ACTION_SELECTOR = '.card-inner-action';

        // The card currently in "entered" state; null when no card is active.
        var currentlyActiveCard = null;

        function getInnerActions(card) {
        return Array.from(card.querySelectorAll(INNER_ACTION_SELECTOR));
        }

        // Reset all cards to their default state: card focusable, inner actions hidden.
        // Skips the active card so entering/exiting doesn't fight itself.
        function resetAllCardsToDefault() {
        document.querySelectorAll(CARD_SELECTOR).forEach(function (card) {
        if (card === currentlyActiveCard) return;
        getInnerActions(card).forEach(function (action) { action.tabIndex = -1; });
        });
        }

        // Enter a card: hide the card from tab order, show and focus its first inner action.
        function enterCard(card) {
        if (currentlyActiveCard && currentlyActiveCard !== card)
        exitCard(currentlyActiveCard);

        currentlyActiveCard = card;
        card.tabIndex = -1; // Remove card from tab cycle while navigating inside it

        var innerActions = getInnerActions(card);
        innerActions.forEach(function (action) { action.tabIndex = 0; });
        if (innerActions[0]) innerActions[0].focus();
        }

        // Exit a card: restore the card to the tab cycle, hide its inner actions.
        function exitCard(card) {
        if (!card) return;
        card.tabIndex = 0;
        getInnerActions(card).forEach(function (action) { action.tabIndex = -1; });
        if (currentlyActiveCard === card) currentlyActiveCard = null;
        }

        // Enter on a card container → enter it. Escape inside an active card → exit it.
        document.addEventListener('keydown', function (e) {
        var target = e.target;

        if (e.key === 'Enter' && target.matches && target.matches(CARD_SELECTOR)) {
        var actions = getInnerActions(target);
        if (actions.length) { e.preventDefault(); enterCard(target); }
        return;
        }

        if (e.key === 'Escape'
        && currentlyActiveCard
        && currentlyActiveCard.contains(target)
        && target !== currentlyActiveCard) {
        e.preventDefault();
        var cardToExit = currentlyActiveCard;
        exitCard(cardToExit);
        cardToExit.focus();
        }
        }, true);

        // Auto-exit a card when focus moves completely outside it.
        // setTimeout(0) defers the check until after the browser has moved focus,
        // because focusout fires before the new activeElement is set.
        document.addEventListener('focusout', function () {
        if (!currentlyActiveCard) return;
        var cardSnapshot = currentlyActiveCard;
        setTimeout(function () {
        if (!cardSnapshot.contains(document.activeElement)) exitCard(cardSnapshot);
        }, 0);
        }, true);

        // ── Mobile-drawer Enter-key navigation fix ─────────────────────────────────
        // MudBlazor's MudNavLink renders as <a> but keyboard-triggered Enter doesn't
        // always fire Blazor's enhanced-navigation click handler. Explicitly calling
        // link.click() guarantees the router intercepts it as a normal navigation.
        // Bubble phase (false) runs after capture, avoiding conflicts with the
        // card-navigation handler above.
        document.addEventListener('keydown', function (e) {
        if (e.key !== 'Enter') return;
        var target = e.target;
        if (!target || !target.closest || !target.closest('.mobile-drawer')) return;

        var navLink = target.matches && target.matches('a[href]')
        ? target
        : target.closest('a[href]');
        if (!navLink) return;

        e.preventDefault();
        navLink.click();
        }, false);

        // ── DOM-change watcher ─────────────────────────────────────────────────────
        // Blazor re-renders patch the DOM without page reloads, which can add new
        // panel headers or card elements. The MutationObserver re-runs setup after
        // every batch of DOM changes. The 50 ms debounce collapses rapid successive
        // mutations (e.g. a full list re-render) into a single setup pass.
        var debounceTimer = null;
        new MutationObserver(function () {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(function () {
        ensureExpansionPanelsAreReachable();
        resetAllCardsToDefault();
        }, 50);
        }).observe(document.documentElement, { childList: true, subtree: true });
        })();
     
